// runScripts is used to copy and execute a set of scripts
func (p *provisioner) runScripts(ctx context.Context, o provisioners.UIOutput, comm communicator.Communicator, scripts []io.ReadCloser) error {
	if p.cancel == nil {
		return errors.New("provisioner is not initialized")
	}

	settings := communicator.SettingsFor(comm)

	retryCtx, cancel := context.WithTimeout(p.ctx, settings.Timeout)
	defer cancel()

	// Wait and retry until we establish the connection
	err := communicator.Retry(retryCtx, func() error {
		return comm.Connect(o)
	})
	if err != nil {
		return err
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-ctx.Done()
		comm.Disconnect()
	}()

	for _, script := range scripts {
		outR, outW := io.Pipe()
		errR, errW := io.Pipe()
		defer outW.Close()
		defer errW.Close()

		go copyUIOutput(o, outR)
		go copyUIOutput(o, errR)

		settings.SetRemotePath(comm.ScriptPath())
		schema := settings.Plan.Path.Schema
		desc := ""
		if schema != nil {
			desc = schema.Description
		}
		remotePath := settings.Plan.Path.Value
		log.Printf("[DEBUG] running remote script %q %s", remotePath, desc)

		if err := comm.UploadScript(remotePath, script); err != nil {
			return fmt.Errorf("Failed to upload script: %v", err)
		}

		settings.Plan.Command = remotePath
		settings.Plan.Stdout = outW
		settings.Plan.Stderr = errW
		settings.Plan.Stdin = nil
		cmd := settings.Plan.NewCommand()
		if err := comm.Start(cmd); err != nil {
			return fmt.Errorf("Error starting script: %v", err)
		}

		if err := cmd.Wait(); err != nil {
			return err
		}

		// Upload a blank follow up file in the same path to prevent residual
		// script contents from remaining on remote machine
		empty := bytes.NewReader([]byte(""))
		if err := comm.Upload(remotePath, empty); err != nil {
			// This feature is best-effort.
			log.Printf("[WARN] Failed to upload empty follow up script: %v", err)
		}
	}

	return nil

